SELECT FROM videos v JOIN users u ON u.id = v.author_id JOIN video_categories vc ON vc.id = v.category_id JOIN v_video_statistics s ON s.video_id = v.id
v.status = 'PUBLISHED'
AND v.title LIKE CONCAT('%', #{keyword}, '%')
AND v.author_id = #{authorId} AND v.category_id = #{categoryId}
ORDER BY v.published_at DESC, v.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM videos v

    v.status = 'PUBLISHED'

        AND v.title LIKE CONCAT('%', #{keyword}, '%')

    AND v.author_id = #{authorId}
    AND v.category_id = #{categoryId}
